class InputReader {
  constructor(input) {
    this.data = input.trim().split(/\s+/);
    this.idx = 0;
  }
  readInt() {
    return parseInt(this.data[this.idx++], 10);
  }
  readArrayOfInt(size, indexFrom = 0) {
    const a = [];
    let ind = indexFrom;
    for (let i = 0; i < size; i++) {
      a[ind++] = parseInt(this.data[this.idx++], 10);
    }
    return a;
  }
  readArrayOfString(size, indexFrom = 0) {
    const a = [];
    let ind = indexFrom;
    for (let i = 0; i < size; i++) {
      a[ind++] = this.data[this.idx++];
    }
    return a;
  }
}

class Utils {
  static ntimes(n, func, returnResults = false) {
    const a = [];
    for (let i = 1; i <= n; i++) {
      const result = func();
      if (returnResults) {
        a[i] = result;
      }
    }
    return a;
  }
  static cumsum(a) {
    let sum = 0;
    for (const k in a) {
      a[k] += sum;
      sum = a[k];
    }
  }
  static diff(a) {
    let prev = 0;
    for (const k in a) {
      const buf = a[k];
      a[k] -= prev;
      prev = buf;
    }
  }
  static bitCount(n) {
    let cnt = 0;
    for (let j = n; j; j >>= 1) {
      cnt += j & 1;
    }
    return cnt;
  }
}

class PrimeUtils {
  static divisorsCache = {
    1: { 1: true },
    2: { 1: true, 2: true }
  };
  static primesList = [];

  static *primes(limit) {
    const len = (limit >> 3) + 1;
    const a = new Uint8Array(len);
    a.fill(85);
    a[0] = 83;
    for (let i = 3; i * i < limit; i += 2) {
      if (a[i >> 3] & (1 << (i % 8))) {
      } else {
        for (let k = i; k * i < limit; k++) {
          const n = k * i;
          a[n >> 3] = a[n >> 3] | (1 << (n % 8));
        }
      }
    }
    yield 2;
    for (let i = 3; i < limit; i += 2) {
      if (!(a[i >> 3] & (1 << (i % 8)))) {
        yield i;
      }
    }
  }

  static divisors(n, lp = 2) {
    if (PrimeUtils.divisorsCache[n]) {
      return PrimeUtils.divisorsCache[n];
    }
    if (PrimeUtils.primesList.length === 0) {
      const primes = [];
      for (const prime of PrimeUtils.primes(1e3)) {
        primes.push(prime);
      }
      PrimeUtils.primesList = primes;
    }
    const r = {};
    for (const p of PrimeUtils.primesList) {
      if (p >= lp) {
        if (n < p * p) {
          r[1] = true;
          r[n] = true;
          break;
        } else if (n % p === 0) {
          for (const pre of [1, p]) {
            const sub = PrimeUtils.divisors(Math.floor(n / p), p);
            for (const nxtStr in sub) {
              const nxt = parseInt(nxtStr, 10);
              r[nxt * pre] = true;
            }
          }
          break;
        }
      }
    }
    PrimeUtils.divisorsCache[n] = r;
    return PrimeUtils.divisorsCache[n];
  }
}

